import{_ as t,o as a,c as s,ag as i}from"./chunks/framework.DXGyWiRo.js";const u=JSON.parse('{"title":"Streaming","description":"How streaming works in DOAI Proxy, including simulated SSE streaming, configuration options, and streaming modes.","frontmatter":{"title":"Streaming","description":"How streaming works in DOAI Proxy, including simulated SSE streaming, configuration options, and streaming modes."},"headers":[],"relativePath":"guides/streaming.md","filePath":"guides/streaming.md"}'),o={name:"guides/streaming.md"};function n(r,e,l,d,c,h){return a(),s("div",null,[...e[0]||(e[0]=[i(`<h1 id="streaming" tabindex="-1">Streaming <a class="header-anchor" href="#streaming" aria-label="Permalink to &quot;Streaming&quot;">​</a></h1><p>DOAI Proxy supports streaming even when the underlying provider doesn&#39;t support native streaming. The proxy accepts requests with <code>stream: true</code>, makes a non-streaming call to the provider, waits for the full response, then simulates SSE streaming.</p><h2 id="how-it-works" tabindex="-1">How It Works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;How It Works&quot;">​</a></h2><ol><li>Proxy accepts requests with <code>stream: true</code></li><li>Makes non-streaming call to provider API</li><li>Waits for full response</li><li>Chunks response based on <code>STREAM_MODE</code> setting</li><li>Sends chunks as SSE (Server-Sent Events)</li><li>Sends <code>[DONE]</code> marker when complete</li></ol><h2 id="streaming-modes" tabindex="-1">Streaming Modes <a class="header-anchor" href="#streaming-modes" aria-label="Permalink to &quot;Streaming Modes&quot;">​</a></h2><h3 id="none-default-recommended" tabindex="-1"><code>none</code> (default, recommended) <a class="header-anchor" href="#none-default-recommended" aria-label="Permalink to &quot;\`none\` (default, recommended)&quot;">​</a></h3><p>Send response as-is with zero artificial delays.</p><ul><li>100% formatting preserved</li><li>Fastest response time</li><li>Recommended for production use</li></ul><p>The entire text is sent as one SSE chunk with <code>finish_reason: null</code>, immediately followed by a <code>finish_reason: &quot;stop&quot;</code> chunk and <code>[DONE]</code>.</p><h3 id="smart-demo-showcase-only" tabindex="-1"><code>smart</code> (demo/showcase only) <a class="header-anchor" href="#smart-demo-showcase-only" aria-label="Permalink to &quot;\`smart\` (demo/showcase only)&quot;">​</a></h3><p>Simulated streaming with boundary-aware chunking.</p><ul><li>May occasionally split markdown formatting (~90% preserved)</li><li>Slower than <code>none</code> mode due to artificial delays</li><li>For demos or when streaming visual effect is desired</li></ul><p>Smart mode uses <code>smartChunkText()</code> which segments text by trying to break at newlines, then whitespace, then extends to avoid splitting Markdown delimiters (<code>**</code>, <code>__</code>, <code>\`\`\`</code>, backticks).</p><h2 id="configuration" tabindex="-1">Configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to &quot;Configuration&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Production: fastest, no formatting issues</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">STREAM_MODE</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">none</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Demo/showcase: character-by-character streaming</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">STREAM_MODE</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">smart</span></span></code></pre></div><h3 id="adjusting-smart-mode" tabindex="-1">Adjusting Smart Mode <a class="header-anchor" href="#adjusting-smart-mode" aria-label="Permalink to &quot;Adjusting Smart Mode&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Smoother, faster</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">STREAM_CHUNK_SIZE</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">25</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">STREAM_DELAY_MS</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">40</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># More realistic, slower</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">STREAM_CHUNK_SIZE</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">8</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">STREAM_DELAY_MS</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">100</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Variable</th><th>Description</th><th>Default</th></tr></thead><tbody><tr><td><code>STREAM_MODE</code></td><td><code>none</code> or <code>smart</code></td><td><code>none</code></td></tr><tr><td><code>STREAM_CHUNK_SIZE</code></td><td>Target chars per SSE chunk (smart mode)</td><td><code>15</code></td></tr><tr><td><code>STREAM_DELAY_MS</code></td><td>Delay between chunks in ms (smart mode)</td><td><code>80</code></td></tr></tbody></table><h2 id="sse-format" tabindex="-1">SSE Format <a class="header-anchor" href="#sse-format" aria-label="Permalink to &quot;SSE Format&quot;">​</a></h2><p>Both modes set <code>Content-Type: text/event-stream</code>, <code>Cache-Control: no-cache</code>, <code>Connection: keep-alive</code>.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>data: {&quot;id&quot;:&quot;chatcmpl-12345&quot;,&quot;object&quot;:&quot;chat.completion.chunk&quot;,&quot;created&quot;:1234567890,&quot;model&quot;:&quot;gpt-3.5-turbo&quot;,&quot;choices&quot;:[{&quot;index&quot;:0,&quot;delta&quot;:{&quot;content&quot;:&quot;Hello&quot;},&quot;finish_reason&quot;:null}]}</span></span>
<span class="line"><span></span></span>
<span class="line"><span>data: {&quot;id&quot;:&quot;chatcmpl-12345&quot;,&quot;object&quot;:&quot;chat.completion.chunk&quot;,&quot;created&quot;:1234567890,&quot;model&quot;:&quot;gpt-3.5-turbo&quot;,&quot;choices&quot;:[{&quot;index&quot;:0,&quot;delta&quot;:{&quot;content&quot;:&quot;!&quot;},&quot;finish_reason&quot;:null}]}</span></span>
<span class="line"><span></span></span>
<span class="line"><span>data: {&quot;id&quot;:&quot;chatcmpl-12345&quot;,&quot;object&quot;:&quot;chat.completion.chunk&quot;,&quot;created&quot;:1234567890,&quot;model&quot;:&quot;gpt-3.5-turbo&quot;,&quot;choices&quot;:[{&quot;index&quot;:0,&quot;delta&quot;:{},&quot;finish_reason&quot;:&quot;stop&quot;}]}</span></span>
<span class="line"><span></span></span>
<span class="line"><span>data: [DONE]</span></span></code></pre></div><h2 id="limitations" tabindex="-1">Limitations <a class="header-anchor" href="#limitations" aria-label="Permalink to &quot;Limitations&quot;">​</a></h2><ul><li><strong>Simulated, not real-time</strong>: Streaming is simulated by chunking non-streaming responses</li><li><strong>Total time</strong>: Longer responses take proportionally longer to stream in smart mode</li><li><strong>Smart mode</strong>: May occasionally split markdown in complex cases (~90% preserved)</li><li><strong>No actual streaming benefit</strong>: Smart mode adds delays, making it slower than none mode</li></ul><h2 id="next-steps" tabindex="-1">Next Steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next Steps&quot;">​</a></h2><ul><li><a href="/examples/streaming">Streaming Examples</a> — usage examples for streaming requests</li><li><a href="/guides/configuration">Configuration</a> — full reference for all environment variables</li></ul>`,25)])])}const m=t(o,[["render",n]]);export{u as __pageData,m as default};
